// Üretilen dosya: tool/ozgun/uret.py. Tarih · Orta Asya Türk devletleri ve göçler (Hun, Göktürk, Uygur, Hazar, Avar) (zor).
const ozHistory6Zor = <(String, String, List<String>, String)>[
  ('Mete\'nin MÖ 209\'da Hun tahtına çıkmadan önce babasının onu hangi topluluğa rehin olarak gönderdiği anlatılır?', 'Yüeçilere', ['Tunguzlara', 'Juan-juanlara', 'Kırgızlara'], 'Rivayete göre Teoman, küçük oğlunu tahta geçirmek için Mete\'yi Yüeçilere rehin göndermiş; Mete kaçıp döndükten sonra iktidarı ele geçirmiştir.'),
  ('Mete\'den sonra Asya Hun tahtına geçen ve Yüeçileri ağır bir yenilgiye uğratarak batıya göçmelerine yol açan hükümdar kimdir?', 'Ki-ok (Lao-şang)', ['Teoman', 'Huhanye', 'Panu (Pu-nu)'], 'Mete\'nin oğlu Ki-ok döneminde Yüeçiler yeniden yenilmiş ve batıya, Seyhun-Ceyhun bölgesine doğru çekilmek zorunda kalmıştır.'),
  ('Han hanedanının Hunlara karşı batıdaki toplulukları kendi yanına çekmek için elçi olarak gönderdiği, yolculuğuyla İpek Yolu\'nun açılmasına katkı sağlayan kişi kimdir?', 'Çang Kien (Zhang Qian)', ['Marco Polo (Venedikli)', 'Hsüan-tsang', 'Priskos'], 'MÖ 2. yüzyılda Han imparatoru Wudi, Hunlara karşı Yüeçilerle ittifak kurmak amacıyla Çang Kien\'i batıya göndermiş; bu seyahat Çin\'in batı ile bağlarını güçlendirmiştir.'),
  ('Asya Hunlarının MÖ 58\'de iki kola ayrılması sonrasında Çin\'e bağlanmayı kabul eden kolun lideri kimdir?', 'Huhanye', ['Çiçi', 'Mete', 'Ki-ok'], 'İç çekişmeler sonucunda Hunlar ikiye bölünmüş; Huhanye Çin\'e bağlanırken kardeşi Çiçi bağımsızlık için batıya çekilmiştir.'),
  ('Çin\'e boyun eğmeyi reddedip batıya, Talas ırmağı çevresine giden ve MÖ 36\'da Çinlilerle savaşırken ölen Hun lideri kimdir?', 'Çiçi', ['Huhanye', 'Panu', 'Liu Yüan'], 'Çiçi Batı Türkistan\'a çekilip orada bir merkez kurmuş, ancak MÖ 36\'da Çin ordusunun saldırısıyla öldürülmüştür.'),
  ('MS 4. yüzyılın başında Kuzey Çin\'de \'Han\' (sonradan Ön Chao) adıyla bir devlet kuran Hun kökenli lider kimdir?', 'Liu Yüan', ['Huhanye', 'Uldız', 'Çiçi'], 'Güney Hunlarının soyundan gelen Liu Yüan 304\'te Kuzey Çin\'de bir devlet kurmuş; bu, \'On Altı Devlet\' döneminin başlangıcıyla ilişkilendirilir.'),
  ('10. yüzyılda Kuzey Çin\'de Sonraki Tang gibi kısa ömürlü hanedanlar kuran ve Batı Göktürklerin bir kolundan geldiği kabul edilen Türk topluluğu hangisidir?', 'Şatolar', ['Kumanlar', 'Avarlar', 'Basmiller'], 'Şato Türkleri, Tang hanedanının yıkılmasından sonraki Beş Hanedan döneminde Kuzey Çin\'de birkaç hanedan kurmuştur.'),
  ('Hun baskısıyla Roma topraklarına giren Vizigotların 378\'de Doğu Roma ordusunu yendiği ve imparator Valens\'in öldüğü savaş hangisidir?', 'Edirne (Hadrianopolis) Savaşı', ['Katalon Savaşı', 'Talas (Atlah) Savaşı', 'Nedao Savaşı'], 'Hun baskısından kaçıp Roma\'ya sığınan Vizigotlar kötü muamele üzerine ayaklanmış ve 378\'de Edirne yakınlarında Roma ordusunu yenmiştir.'),
  ('Katalon Ovası Savaşı\'nda Hunların karşısındaki ittifakın en güçlü Germen unsuru, daha önce Hun baskısıyla Roma topraklarına girmiş olan hangi topluluktur?', 'Vizigotlar', ['Ostrogotlar', 'Gepidler', 'Vandallar'], 'Katalon\'da Aetius\'un yanında Kral Theodorik yönetimindeki Vizigotlar savaşmıştır; Ostrogot ve Gepidler ise Hun saflarındaydı.'),
  ('Attila\'nın büyük oğlu İlek\'in, Gepid önderliğindeki bağlı kavimlerin ayaklanmasıyla öldüğü 454 tarihli savaş hangisidir?', 'Nedao Savaşı', ['Katalon Savaşı', 'Talas Savaşı', 'Pai-teng Savaşı'], 'Nedao Savaşı\'nda Gepid kralı Ardarik\'in önderliğindeki ittifak Hunları yenmiş, İlek savaşta ölmüştür.'),
  ('Attila\'nın oğullarından biri olan ve Bizans\'a karşı mücadelesini 469\'daki ölümüne kadar sürdüren Hun hükümdarı kimdir?', 'Dengizik', ['İrnek', 'Bleda', 'Rua'], 'Dengizik, Bizans\'tan vergi almaya devam etmek için savaşmış, 469\'da Bizans ordusuyla çarpışırken ölmüş ve başı İstanbul\'da teşhir edilmiştir.'),
  ('Ak Hun hükümdarı Ahşunvar\'ın 484\'te yendiği ve savaşta ölen Sasani hükümdarı kimdir?', 'Firuz', ['I. Hüsrev Anuşirvan', 'II. Şapur', 'Yezdicerd'], 'Ahşunvar, Sasani hükümdarı Firuz\'u yenmiş; Firuz savaşta ölmüş ve Sasaniler bir süre Ak Hunlara vergi ödemek zorunda kalmıştır.'),
  ('Ak Hunların Kuzey Hindistan\'a yaptığı akınların bölgedeki hangi devletin zayıflamasına katkıda bulunduğu kabul edilir?', 'Gupta İmparatorluğu', ['Babür İmparatorluğu', 'Maurya İmparatorluğu', 'Delhi Sultanlığı'], '5. yüzyılın sonu ve 6. yüzyılın başında Ak Hunların Hindistan\'daki ilerleyişi, Gupta İmparatorluğu\'nun parçalanmasını hızlandırmıştır.'),
  ('Türk sözcüğünün anlamı farklı kaynaklarda farklı açıklanmıştır. Çin kaynaklarında bu adın hangi anlama geldiği belirtilir?', 'Miğfer', ['Töreli', 'Olgunluk çağı', 'Türemiş'], 'Çin kaynakları, Göktürklerin yaşadığı Altay\'daki bir dağın miğfere benzediğini ve \'Türk\' adının bu anlamla ilişkili olduğunu yazar. \'Töreli\' Ziya Gökalp\'e, \'olgunluk çağı\' Kaşgarlı Mahmut\'a aittir.'),
  ('İstemi Yabgu\'nun 568\'de Bizans\'a gönderdiği elçilik heyetinin başkanı olan Soğdlu tüccar kimdir?', 'Maniak', ['Zemarkhos', 'Priskos', 'Valentinos'], 'Soğdlu Maniak, Göktürk elçisi olarak Bizans imparatoru II. Justinus\'un sarayına gitmiştir. Zemarkhos ve Valentinos ise Bizans\'ın Türklere gönderdiği elçilerdir.'),
  ('Göktürklerin Bizans\'a elçisine karşılık olarak İstemi Yabgu\'nun ordugâhına gelen Bizans elçisi kimdir?', 'Zemarkhos', ['Maniak', 'Priskos', 'Prokopios'], 'Bizans imparatoru II. Justinus, Göktürk elçiliğine karşılık Zemarkhos\'u İstemi\'nin yanına göndermiş; elçi Türk sarayındaki tören ve gelenekleri kaydetmiştir.'),
  ('576\'da Bizans\'ın Sasanilerle barış yapmasına öfkelenen Göktürklerin Kırım\'daki hangi Bizans kentini ele geçirdiği bilinir?', 'Kerç (Bosporus)', ['Trabzon (Trapezus)', 'Kartaca', 'Antakya (Antiokheia)'], 'Bizans\'ın Göktürkleri yalnız bırakıp Sasanilerle anlaşması ilişkileri bozmuş; Göktürkler 576\'da Kırım\'daki Bosporus\'u (Kerç) almıştır.'),
  ('Kuzey Çin\'deki iki devletin vergi ödemesi için \'Güneydeki iki oğlum bana bağlı kaldıkça yoksulluktan korkmam\' dediği aktarılan Göktürk kağanı kimdir?', 'Taspar Kağan', ['Bumin Kağan', 'Bilge Kağan', 'İlteriş Kutluk Kağan'], 'Taspar Kağan (572–581) döneminde Kuzey Çin\'deki iki hanedan Göktürklere düzenli ipek veriyordu; Taspar bu durumu bu sözlerle övmüştür.'),
  ('Göktürk Devleti 582\'de Doğu ve Batı olarak ikiye ayrıldığında Batı Göktürklerin başında bulunan, İstemi\'nin oğlu olan hükümdar kimdir?', 'Tardu', ['İşbara', 'Kapgan', 'Kül Tigin'], 'Taht kavgaları ve Çin\'in kışkırtmalarıyla 582\'de bölünen devlette Batı\'yı İstemi\'nin oğlu Tardu, Doğu\'yu İşbara Kağan yönetmiştir.'),
  ('Batı Göktürklerinin en güçlü dönemini yaşatan ve 627\'de Bizans imparatoru Herakleios ile Sasanilere karşı iş birliği yapan hükümdar kimdir?', 'Tong Yabgu', ['İstemi Yabgu', 'Tardu Kağan', 'Sulu Kağan'], 'Tong Yabgu (yaklaşık 618–630) döneminde Batı Göktürkler güçlenmiş; Herakleios\'la birlikte Kafkasya\'da Sasanilere karşı harekât yapılmıştır.'),
  ('Kapgan Kağan\'ın 716\'da hayatını kaybetmesine yol açan olay hangisidir?', 'İsyan eden Bayırku boyuna karşı yaptığı sefer dönüşünde pusuya düşürülmesi', ['Çin sarayında zehirlenerek öldürülmesi', 'Hazar Denizi\'nde fırtınaya yakalanarak boğulması', 'Bizans ordusuyla yaptığı bir meydan savaşında ölmesi'], 'Kapgan Kağan, ayaklanan Bayırkulara karşı başarılı bir seferden dönerken pusuya düşürülüp öldürülmüştür.'),
  ('Bilge Kağan\'ın 734\'teki ölümüyle ilgili olarak kaynaklarda aktarılan bilgi hangisidir?', 'Buyruklarından biri tarafından zehirlenerek öldürülmüştür', ['Çin\'e karşı yapılan büyük bir savaşta kılıçla öldürülmüştür', 'Batıya sefer sırasında İdil Nehri\'nde boğulmuştur', 'Tahtı oğluna bırakıp manastıra çekilerek yaşlılıktan ölmüştür'], 'Bilge Kağan, buyruklarından (bakanlarından) biri tarafından zehirlenmiş ve ölmeden önce suçluları cezalandırmıştır.'),
  ('Orhun yazıtlarının ilk tam çevirisini 1894\'te yayımlayan Alman asıllı Türkolog kimdir?', 'Wilhelm Radloff', ['Vilhelm Thomsen', 'Aurel Stein', 'Albert von Le Coq'], 'Thomsen\'in alfabeyi çözmesinin ardından Radloff, yazıtların ilk tam çevirisini 1894\'te yayımlamıştır.'),
  ('Göktürk alfabesiyle yazılmış metinlerde sözcükleri birbirinden ayırmak için çoğunlukla hangi işaret kullanılır?', 'İki nokta', ['Kısa yatay çizgi', 'Küçük bir daire', 'Ters virgül'], 'Göktürk yazıtlarında sözcükler genellikle üst üste konmuş iki nokta ile birbirinden ayrılır.'),
  ('Bögü Kağan\'ın 779\'da öldürülmesiyle ilgili olarak kaynaklarda aktarılan neden hangisidir?', 'Çin\'e karşı sefer planına karşı çıkan akrabası Tun Baga Tarkan\'ın ayaklanması', ['Bizans elçilerinin onu zehirlemesi', 'Kırgızların Ordu-Balık\'ı basarak kağanı esir alıp öldürmesi', 'Mani rahiplerinin onu tahttan indirmesi'], 'Soğdluların teşvikiyle Çin\'e sefer düşünen Bögü Kağan\'a karşı çıkan Tun Baga Tarkan onu öldürerek tahta geçmiştir.'),
  ('Budist bir metin olan ve Uygurcaya Şıngku Seli Tutung tarafından çevrildiği bilinen eser hangisidir?', 'Altun Yaruk', ['Irk Bitig', 'Kutadgu Bilig', 'Dede Korkut Kitabı'], 'Altun Yaruk (Altın Işık), Uygur dönemine ait Budist bir sutradır; Uygurcaya Şıngku Seli Tutung tarafından çevrilmiştir.'),
  ('Turfan çevresindeki Bezeklik mağaralarında bulunan Uygur duvar resimlerinin önemli bir bölümünü 20. yüzyıl başında Berlin\'e götüren araştırmacı kimdir?', 'Albert von Le Coq', ['Vilhelm Thomsen', 'Wilhelm Radloff', 'Nikolay Yadrintsev'], 'Alman kazı heyetleriyle Turfan\'da çalışan Albert von Le Coq, Bezeklik\'ten pek çok duvar resmini Berlin\'e taşımıştır.'),
  ('Turfan Uygur Devleti\'nin hükümdarlarının kullandığı ve \'kutlu, saygıdeğer hükümdar\' anlamına gelen unvan hangisidir?', 'İdikut', ['Kağan Bek', 'Tanhu', 'Yabgu Şad'], 'Turfan (Koço) Uygur hükümdarları \'İdikut\' unvanını kullanmıştır.'),
  ('Kansu Uygur Devleti 11. yüzyılın başlarında hangi topluluk tarafından ortadan kaldırılmıştır?', 'Tangutlar', ['Karluklar', 'Hazarlar', 'Karahanlılar'], 'Kansu Uygurlarının devleti 1028 dolaylarında Tangutların saldırısıyla sona ermiştir; Uygur nüfusu ise bölgede yaşamayı sürdürmüştür.'),
  ('Bugün Çin\'in Kansu (Gansu) bölgesinde yaşayan ve 840 sonrası göç eden Uygurların torunları sayılan topluluk hangi adla bilinir?', 'Sarı Uygurlar', ['Kara Türgişler', 'Ak Hunlar', 'Kara Bulgarlar'], 'Kansu\'ya yerleşen Uygurların soyundan gelen ve Budist geleneği sürdüren topluluk \'Sarı Uygurlar\' olarak bilinir.'),
  ('Kırgızların Uygurları yıktıktan sonra Ötüken\'de uzun süre kalamayıp 10. yüzyılda bölgeden çıkarılmasında hangi topluluğun etkisi vardır?', 'Kitanlar (Hıtaylar)', ['Peçenekler (Patzinaklar)', 'Tabgaçlar (Tobalar)', 'Hazarlar'], 'Kırgızlar 920\'li yıllarda Kitanlar tarafından Moğolistan\'dan çıkarılmış ve yeniden Yenisey bölgesine çekilmiştir.'),
  ('Türgiş Devleti\'nin kurucusu olarak kabul edilen hükümdar kimdir?', 'Uç Elig (Ucele) Kağan', ['Sulu Kağan', 'Tong Yabgu', 'Kül Çor'], 'Türgiş Devleti\'ni 7. yüzyılın sonlarında Uç Elig Kağan kurmuştur; Sulu Kağan ise devletin en güçlü dönemindeki hükümdardır.'),
  ('Sulu Kağan\'ın 738\'de öldürülmesinden sonra Türgişlerde iki kola ayrılmaya yol açan iç çekişme hangi boy grupları arasında yaşanmıştır?', 'Sarı Türgişler ile Kara Türgişler', ['Kuzey Hunları ile Güney Hunları', 'İç Oğuzlar ile Dış Oğuzlar', 'Kutrigurlar ile Utrigurlar'], 'Sulu\'nun ölümünden sonra Türgiş beyleri \'Sarı\' ve \'Kara\' Türgiş olarak ikiye bölünüp çekişmiş, devlet zayıflamıştır.'),
  ('Karluk hükümdarlarının 8. yüzyılda kullandığı ve Göktürklerde de batı kanadı yöneticisini ifade eden unvan hangisidir?', 'Yabgu', ['Tanhu', 'İdikut', 'Ajo'], 'Karluk hükümdarları \'Yabgu\' unvanını kullanmıştır; bu unvan Göktürklerde İstemi\'nin taşıdığı unvanla aynıdır.'),
  ('742\'de Göktürklere karşı kurulan ittifakın ilk aşamasında kağanlık makamına geçen ancak kısa süre sonra Uygurlara yenilen boy hangisidir?', 'Basmiller', ['Kırgızlar', 'Türgişler', 'Kimekler'], 'Ayaklanmanın başında Basmil lideri kağan ilan edilmiş, fakat Uygurlar ve Karluklar kısa sürede Basmilleri yenmiştir.'),
  ('Bayan Kağan\'ın Langobardlarla iş birliği yaparak 567\'de ortadan kaldırdığı Germen kavmi hangisidir?', 'Gepidler', ['Vizigotlar', 'Franklar', 'Saksonlar'], 'Avarlar ve Langobardlar birlikte Gepidleri yenmiş; ardından Langobardlar İtalya\'ya göçmüş, Avarlar da Pannonia\'ya yerleşmiştir.'),
  ('Avarların 582\'de Bizans\'tan aldığı ve Tuna-Sava bölgesinde önemli bir kale-kent olan yer hangisidir?', 'Sirmium', ['Kerç', 'Sarkel', 'Margus'], 'Bayan Kağan uzun bir kuşatmadan sonra 582\'de Sirmium\'u (bugünkü Sremska Mitrovica) ele geçirmiştir.'),
  ('Hazar yönetiminde kağanın yanında devlet işlerini fiilen yürüten ve orduya komuta eden yöneticinin unvanı hangisidir?', 'Bek (İşad)', ['Tudun', 'İdikut (kutlu hükümdar)', 'Tanhu'], 'Hazarlarda kağan kutsal ve sembolik bir hükümdar konumundaydı; günlük yönetim ve ordu komutası Bek ya da İşad denilen yöneticideydi.'),
  ('10. yüzyılda Endülüs Emevi devlet adamı Hasday ibn Şaprut ile bir Hazar hükümdarı arasında geçtiği bilinen yazışmalar hangi konuda önemli bilgi verir?', 'Hazarların Museviliği kabul etmesi ve devletin yapısı', ['Hazarların İslam\'ı kabul ettiği tarih', 'Hazarların Hindistan\'a düzenlediği seferler ve oradan getirilen ganimetler', 'Hazar alfabesinin Kiril\'e dönüşmesi'], '\'Hazar mektupları\' olarak bilinen yazışmalarda Hazar hükümdarı Yusuf, atalarının Museviliğe geçişini ve ülkesinin sınırlarını anlatır.'),
  ('Bizans imparatoru V. Konstantin\'in bir Hazar prensesiyle evlenmesinden doğan ve \'Hazar\' lakabıyla anılan imparator kimdir?', 'IV. Leon', ['II. Basileios', 'I. Justinianus', 'Herakleios'], 'V. Konstantin\'in eşi Hazar prensesi Çiçek\'ten (İrene) doğan IV. Leon, annesinin kökeni nedeniyle \'Hazar Leon\' olarak anılmıştır.'),
  ('Hazarlara karşı ayaklanıp 9. yüzyılda Macarlara katılan ve Macar boy birliğinde yer alan Hazar kökenli topluluklara ne ad verilir?', 'Kabarlar', ['Kutrigurlar', 'Bayırkular', 'Basmiller'], 'Hazar iç çekişmeleri sonrasında ayrılan Kabar boyları Macarlara katılmış ve onlarla birlikte Pannonia\'ya göçmüştür.'),
  ('Tuna Bulgar hükümdarı Tervel\'in 705\'te tahtını kaybetmiş Bizans imparatoru II. Justinianus\'a yardım edip onu yeniden tahta çıkarması ona hangi unvanı kazandırmıştır?', 'Kaisar (Sezar)', ['Basileus', 'Patrikios (patrisyen)', 'Despot'], 'Tervel\'in yardımıyla İstanbul\'a dönen II. Justinianus, Bulgar hükümdarına \'Kaisar\' unvanını vermiştir.'),
  ('717–718\'deki büyük Arap kuşatması sırasında Bizans\'a yardım ederek kuşatmanın kalkmasına katkı sağlayan Türk devleti hangisidir?', 'Tuna Bulgar Devleti', ['Avrupa Avar Kağanlığı', 'Peçenek boy birliği', 'Uygur Kağanlığı'], 'Tervel yönetimindeki Bulgarlar, İstanbul\'u kuşatan Arap ordusuna karadan saldırarak ağır kayıplar verdirmiş ve kuşatmanın sona ermesine katkıda bulunmuştur.'),
  ('Bugün İdil boyunda yaşayan ve dilleri Türk dillerinin Oğur (Bulgar) koluna bağlanan topluluk hangisidir?', 'Çuvaşlar', ['Kazaklar', 'Türkmenler', 'Yakutlar'], 'Çuvaşça, Türk dilleri arasında Oğur kolunun yaşayan tek temsilcisidir ve İdil Bulgarlarının diliyle ilişkilendirilir.'),
  ('İdil Bulgarlarının başkenti olan ve İdil ile Kama ırmaklarının birleştiği bölgeye yakın kurulan kent hangisidir?', 'Bulgar şehri', ['İtil şehri', 'Pliska şehri', 'Sarkel kalesi'], 'İdil Bulgarlarının merkezi, devletle aynı adı taşıyan Bulgar şehridir; kalıntıları bugün Tataristan\'dadır.'),
  ('Bizans imparatoru VII. Konstantinos\'un yazdığı eserde Peçeneklerin kaç boydan oluştuğu belirtilir?', 'Sekiz', ['On iki', 'Yirmi dört', 'Beş'], 'VII. Konstantinos Porphyrogennetos, Peçeneklerin sekiz boydan oluştuğunu ve her boyun kendi beyi tarafından yönetildiğini yazar.'),
  ('972\'de Dinyeper çağlayanları yakınında Peçeneklerin pusuya düşürüp öldürdüğü Kiev prensi kimdir?', 'Svyatoslav', ['Bilge Yaroslav', 'Vladimir', 'Oleg'], 'Hazarları yıkan Kiev prensi Svyatoslav, Bizans\'tan dönerken Peçenek beyi Küre tarafından pusuya düşürülüp öldürülmüştür.'),
  ('Peçeneklerin Bizans\'a karşı son büyük yenilgisini aldığı ve Bizans\'ta bu zaferin anısına bir şenlik düzenlendiği savaş 1122\'de hangi imparator döneminde yaşanmıştır?', 'II. Ioannes Komnenos', ['I. Justinianus', 'II. Basileios', 'Herakleios'], '1122\'de II. Ioannes Komnenos\'un ordusu Peçenekleri yenmiş; bu yenilgiden sonra Peçenekler bağımsız bir güç olarak tarih sahnesinden çekilmiştir.'),
  ('Kıpçakların İrtiş Irmağı çevresinde yer aldığı ve Kıpçakların da içinde bulunduğu boy birliği hangisidir?', 'Kimek birliği', ['Onogur birliği', 'Dokuz Oğuz birliği', 'Üç Karluk birliği'], 'Kıpçaklar başlangıçta İrtiş havzasındaki Kimek boy birliğinin bir parçasıydı; 11. yüzyılda batıya yayılarak bozkırın hâkimi oldular.'),
  ('1185\'te bir Rus prensinin Kuman-Kıpçaklara karşı başarısız seferini anlatan ünlü eski Rus edebiyatı metni hangisidir?', 'İgor Seferi Destanı', ['Manas Destanı', 'Nibelungen Destanı', 'Şehname'], 'İgor Seferi Destanı, Novgorod-Seversk prensi İgor\'un Polovetslere (Kumanlara) karşı yenilgiyle sonuçlanan seferini anlatır.'),
  ('Moğol istilası karşısında 1239\'da Kumanlardan büyük bir grubu Macar kralının izniyle Macaristan\'a göç ettiren Kuman lideri kimdir?', 'Köten Han', ['Küre Bey', 'Bayan Kağan', 'Kubrat Han'], 'Köten Han, Moğollardan kaçarak Kuman boylarını Macaristan\'a götürmüş; Kumanlar zamanla Hristiyanlaşıp Macar halkına karışmıştır.'),
  ('559\'da Zabergan önderliğinde Tuna\'yı geçip İstanbul önlerine kadar ilerleyen ve Bizans komutanı Belisarios tarafından geri püskürtülen Hun kökenli topluluk hangisidir?', 'Kutrigurlar', ['Uygurlar', 'Türgişler', 'Kırgızlar'], 'Hunların dağılmasından sonra Karadeniz\'in kuzeyinde yaşayan Kutrigurlar 559\'da Zabergan önderliğinde İstanbul\'u tehdit etmiştir.'),
  ('Göktürklerde bağlı halklar üzerinde vergi toplayan ve kağan adına denetim yapan görevliye ne ad verilirdi?', 'Tudun', ['Ayguçı', 'Tigin', 'Kam'], 'Tudun, bağımlı topluluklardan vergi toplayan ve onları denetleyen Göktürk görevlisidir.'),
  ('Eski Türk devletlerinde kağana bağlı bir topluluğun başındaki yerel yöneticiye verilen ve Uygurlarda da görülen unvan hangisidir?', 'Elteber', ['Tanhu', 'İdikut', 'Tigin'], 'Elteber, kağanlığa bağlı boy ve toplulukların başındaki yöneticilere verilen unvandır.'),
  ('Göktürklerde yazışmaları yürüten kâtiplere ne ad verilirdi?', 'Bitikçi', ['Tamgacı', 'Tudun', 'Buyruk'], '\'Bitig\' yazı, kitap anlamına gelir; bitikçi devlet yazışmalarını yürüten kâtiptir.'),
  ('Eski Türklerde yönlerin renklerle anlatılması geleneğinde kuzey yönü hangi renkle ifade edilirdi?', 'Kara', ['Ak', 'Kızıl', 'Gök'], 'Eski Türk renk-yön simgeciliğinde kuzey kara, güney kızıl, batı ak, doğu ise gök (mavi) renkle gösterilir.'),
  ('Oğuz Kağan Destanı\'nın bilinen en eski yazılı nüshalarından biri hangi alfabeyle yazılmıştır?', 'Uygur alfabesi', ['Göktürk alfabesi', 'Latin alfabesi', 'Kiril alfabesi'], 'Paris\'te bulunan ünlü nüsha Uygur harfleriyle yazılmıştır ve İslamiyet öncesi unsurları korumasıyla bilinir.'),
  ('Ergenekon Destanı\'nda Türkleri vadiden çıkaran önder olarak anılan kişi kimdir?', 'Börteçine', ['Oğuz Kağan', 'Alp Er Tonga', 'Manas'], 'Destana göre Türkleri Ergenekon\'dan çıkaran önder Börteçine\'dir; çıkış günü her yıl törenle kutlanmıştır.'),
  ('Uygur Göç Destanı\'na göre Uygurların yurtlarını bırakıp göç etmesine yol açan olay hangisidir?', 'Ülkeye bereket getiren kutlu kayanın Çinlilere verilmesi', ['Bir depremle bütün otlakların sular altında kalması', 'Bizans ordusunun Ordu-Balık\'ı ele geçirip yakması', 'Kağanın Maniheizmi kabul etmesi'], 'Destana göre Çinliler, Uygurları koruyan kutlu kayayı ele geçirip parçalayınca ülkede kıtlık ve felaketler başlamış, Uygurlar göç etmek zorunda kalmıştır.'),
  ('Konusu Büyük İskender\'in Orta Asya seferine karşı Türklerin mücadelesi olan ve Saka dönemine bağlanan destan hangisidir?', 'Şu Destanı', ['Göç Destanı', 'Türeyiş Destanı', 'Manas Destanı'], 'Şu Destanı, Türk hükümdarı Şu\'nun İskender\'in ordusuna karşı mücadelesini anlatır; Kaşgarlı Mahmut eserinde bu destana yer vermiştir.'),
  ('Mete MÖ 209\'da tahta çıkmış, Asya Hunları ise MS 48\'de Kuzey ve Güney olarak ikiye ayrılmıştır. Milat takviminde sıfır yılı bulunmadığına göre bu iki olay arasında kaç yıl vardır?', '256', ['257', '258', '161'], 'MÖ 209\'dan MS 1\'e 209 yıl, MS 1\'den MS 48\'e 47 yıl geçer; toplam 209 + 47 = 256 yıldır.'),
  ('Mete MÖ 209\'da Hun tahtına çıkmış, Bumin ise MS 552\'de Göktürk Devleti\'ni kurmuştur. Sıfır yılı olmadığı dikkate alındığında bu iki olay arasında kaç yıl vardır?', '760', ['761', '343', '759'], 'MÖ 209\'dan MS 1\'e 209 yıl, MS 1\'den 552\'ye 551 yıl geçer: 209 + 551 = 760 yıl.'),
  ('Orhun yazıtlarında \'Altun yış\' olarak anılan sıradağlar bugün hangi adla bilinir?', 'Altay Dağları', ['Tanrı Dağları', 'Ural Dağları', 'Kafkas Dağları'], 'Eski Türkçede \'yış\' dağlık orman demektir; \'Altun yış\' Altay Dağları\'nı ifade eder. Göktürklerin ilk yurdu da Altay çevresidir.'),
  ('Orhun yazıtlarında Kırgız ülkesine yapılan seferde aşıldığı anlatılan \'Kögmen\' dağları bugün hangi dağlara karşılık gelir?', 'Sayan Dağları', ['Hindukuş Dağları', 'Kingan Dağları', 'Pamir Dağları'], 'Kögmen, Yenisey havzasını Moğolistan\'dan ayıran Sayan Dağları\'dır; yazıtlar Kırgızlara karşı seferde bu dağların aşıldığını anlatır.'),
  ('Bilge Kağan yazıtında batıda ordunun ulaştığı en uzak nokta olarak anılan, Semerkant ile Belh arasındaki geçit hangisidir?', 'Demir Kapı', ['Derbent Geçidi', 'Hayber Geçidi', 'Kilikya Kapıları'], 'Yazıtta Göktürk ordusunun batıda İnci Irmağı\'nı (Seyhun) geçip Demir Kapı\'ya kadar ulaştığı anlatılır.'),
  ('Orhun yazıtlarında \'Yinçü Ögüz\' (İnci Irmağı) olarak geçen ırmak hangisidir?', 'Seyhun', ['Orhun', 'Selenga', 'İdil (Volga) Irmağı\'nın yukarı kolu'], 'İnci Irmağı, Göktürk ordusunun batıya seferinde geçtiği Seyhun Nehri\'dir.'),
  ('Bilge Kağan yazıtında güneyde \'Tüpüt\'e az kaldı\' denilerek ordunun yaklaştığı belirtilen ülke bugün hangi bölgeye karşılık gelir?', 'Tibet', ['Hindistan', 'İran', 'Kore'], 'Eski Türkçede Tüpüt Tibet\'i ifade eder; yazıt Göktürk seferlerinin güneyde Tibet sınırlarına yaklaştığını anlatır.'),
  ('Gotların tarihini yazan ve Attila\'nın ölümünü, cenaze törenini ayrıntılarıyla aktaran 6. yüzyıl yazarı kimdir?', 'Jordanes', ['Herodotos', 'Tacitus', 'Menandros'], 'Jordanes\'in \'Getica\' adlı eseri, Attila\'nın ölümü ve Hunların yas törenleri hakkında temel kaynaklardandır.'),
  ('Kuzey Hindistan\'da hüküm süren ve Hint kaynaklarında Budistlere karşı sert tutumuyla anılan Ak Hun hükümdarı kimdir?', 'Mihirakula', ['Ahşunvar', 'Asparuh', 'Tardu'], 'Ak Hun hükümdarı Toramana\'nın oğlu Mihirakula, 6. yüzyılın başında Kuzey Hindistan\'da hüküm sürmüş ve Budist manastırlarına yönelik saldırılarıyla tanınmıştır.'),
  ('Orhun yazıtlarında \'On Ok budunu\' olarak anılan topluluk hangi devletin halkını ifade eder?', 'Batı Göktürkleri', ['Doğu Göktürkleri', 'Kırgızlar', 'Hazarlar'], 'Batı Göktürkler on boydan oluştuğu ve her boy beyine bir ok verildiği için \'On Ok\' adıyla anılmıştır.'),
  ('630\'da Doğu Göktürklerin yıkılmasından sonra Ötüken\'de kısa süre egemenlik kuran ve 646\'da Uygurlar ile Tang ordularınca yıkılan Türk boyu devleti hangisidir?', 'Sir Tarduş (Sir-Yanto)', ['Türgiş (Yedisu boyu)', 'Basmil', 'Kimek'], 'Sir Tarduşlar Doğu Göktürklerin çöküşünden yararlanarak Ötüken\'de bir kağanlık kurmuş, ancak 646\'da yıkılmıştır.'),
  ('821 dolaylarında Uygur başkentini ziyaret eden ve şehrin büyüklüğünü, on iki demir kapısını anlatan Arap seyyah kimdir?', 'Temim bin Bahr', ['İbn Battuta', 'Mesudi', 'İbn Fadlan'], 'Temim bin Bahr, Uygur başkenti Ordu-Balık\'ı görmüş; kalabalık çarşılarını ve büyük demir kapılarını kaydetmiştir.'),
  ('Batı dillerinde Macaristan ve Macarlar için kullanılan \'Hungary\' (Hungarian) adının hangi Türk boy birliğinin adından geldiği kabul edilir?', 'Onogurlar', ['Kıpçaklar', 'Uygurlar', 'Karluklar'], 'Macarlar uzun süre Onogur-Bulgar çevresinde yaşamış ve Avrupalılarca bu adla anılmıştır; \'Hungary\' adı Onogur sözcüğüne bağlanır.'),
  ('Han hanedanının Hunlara karşı uzun süren savunma ve evlilik siyasetini bırakıp büyük askerî seferlerle saldırıya geçtiği dönemin imparatoru kimdir?', 'Wudi (Vu-ti)', ['Kao-ti (Liu Bang)', 'Qin Shi Huang', 'Taizong'], 'Han imparatoru Wudi (MÖ 141–87) Hunlara karşı büyük seferler düzenlemiş, batıyla bağlantı kurmak için de elçiler göndermiştir.'),
  ('Bizans kaynaklarında \'Silziboulos\' ya da \'Dizabulos\' adıyla anılan Göktürk hükümdarı kimdir?', 'İstemi Yabgu', ['Bumin Kağan', 'Mukan Kağan', 'Tardu Kağan'], 'Bizans kaynakları İstemi Yabgu\'yu bu adlarla anar; Menandros, Göktürk-Bizans elçilikleri hakkında temel kaynaktır.'),
  ('Göktürk-Bizans elçilik ilişkileri ve Zemarkhos\'un Türk ülkesine yolculuğu hakkında en ayrıntılı bilgiyi veren Bizans tarihçisi kimdir?', 'Menandros', ['Priskos', 'Jordanes', 'Herodotos'], 'Menandros Protektor, 6. yüzyılın ikinci yarısındaki Göktürk-Bizans elçiliklerini ayrıntılı biçimde anlatmıştır. Priskos ise Attila dönemini anlatır.'),
  ('Yenikent, Semerkant ve Taşkent gibi Orta Asya şehir adlarında görülen \'kent\' sözcüğünün hangi dilden geldiği kabul edilir?', 'Soğdca', ['Çince', 'Arapça', 'Grekçe'], '\'Kent\' (kand) sözcüğü Soğdca kökenlidir; Soğdlularla yoğun ilişki Türkçeye bu sözcüğü kazandırmıştır.'),
  ('Avrupa Hun hükümdarı Attila\'nın babasının adı aşağıdakilerden hangisidir?', 'Muncuk', ['Rua', 'Balamir', 'Uldız'], 'Attila ile Bleda, Muncuk\'un oğullarıdır; Rua ise onların amcasıdır.'),
  ('Bazı tarihçilerin Hazar egemenliği döneminde Karadeniz\'in kuzeyinde ticaretin ve farklı toplulukların barış içinde yaşamasını anlatmak için kullandığı kavram hangisidir?', 'Pax Khazarica (Hazar Barışı)', ['Pax Romana (Roma Barışı)', 'Reconquista', 'Pax Mongolica (Moğol Barışı dönemi)'], 'Hazar egemenliği altında bölgede görece bir istikrar sağlanmış, ticaret yolları güvenli hâle gelmiştir; bu durum \'Pax Khazarica\' olarak adlandırılır.'),
  ('Avrupa Avarlarının Macaristan ovasında halka biçiminde surlarla çevrili, hazinelerinin saklandığı merkezlerine Batı kaynaklarında ne ad verilmiştir?', 'Ring (Hring)', ['Kremlin (kale-saray)', 'Akropolis', 'Forum'], 'Frank kaynakları Avarların halka biçimindeki tahkimatlı merkezlerine \'Ring\' adını vermiş; Şarlman\'ın orduları bu merkezi ve hazinesini ele geçirmiştir.'),
  ('7. yüzyılın başlarında Avar egemenliğine karşı ayaklanarak Orta Avrupa\'da kısa ömürlü bir Slav birliği kuran tüccar kimdir?', 'Samo', ['Svyatoslav', 'Kubrat', 'Odoakr'], 'Frank kökenli tüccar Samo, 620\'lerde Avarlara karşı ayaklanan Slavların başına geçmiş ve bir Slav birliği oluşturmuştur.'),
  ('12. yüzyılın sonunda Bizans\'a karşı ayaklanan Asen kardeşlerin İkinci Bulgar Devleti\'ni kurmasında askerî destek sağlayan bozkır topluluğu hangisidir?', 'Kumanlar', ['Avarlar', 'Hunlar', 'Hazarlar'], 'Asen kardeşler 1185 sonrası ayaklanmada Kuman süvarilerinden büyük destek almış; Kumanlar Balkan siyasetinde etkin bir güç olmuştur.'),
  ('Orhun Vadisi\'ndeki Göktürk yazıtlarını 1889\'da bulup bilim dünyasına tanıtan Rus araştırmacı kimdir?', 'Nikolay Yadrintsev', ['Vilhelm Thomsen', 'Aurel Stein', 'Albert von Le Coq'], 'Yadrintsev 1889\'da Orhun Vadisi\'nde Kül Tigin ve Bilge Kağan yazıtlarını bularak tanıtmış; ardından bilimsel heyetler bölgeye gitmiştir.'),
  ('Göktürk harfli yazıtların Avrupa\'da ilk kez tanınmasını sağlayan, Sibirya\'da esir kaldığı yıllarda gördüğü yazıtların çizimlerini 1730\'da yayımlayan İsveçli subay kimdir?', 'Philip Johan von Strahlenberg', ['Wilhelm Radloff', 'Nikolay Yadrintsev', 'Vilhelm Thomsen'], 'Strahlenberg, Poltava\'dan sonra Sibirya\'ya sürülen İsveçli subaylardandır; 1730\'daki kitabında Yenisey bölgesindeki yazıtların çizimlerini yayımlamıştır.'),
  ('615\'te Sui imparatoru Yang\'ı Yanmen kalesinde kuşatan Doğu Göktürk kağanı kimdir?', 'Şipi Kağan', ['Bumin Kağan', 'Kapgan Kağan', 'Bögü Kağan'], 'Doğu Göktürk kağanı Şipi, Sui hanedanının zayıf döneminde imparatoru Yanmen\'de kuşatmıştır; bu olay Sui\'nin itibarını sarsmıştır.'),
  ('711\'de Kül Tigin ve Tonyukuk\'un yönettiği Göktürk ordusunun Türgişleri yendiği savaş hangisidir?', 'Bolçu Savaşı', ['Talas Savaşı', 'Katalon Savaşı', 'Nedao Savaşı'], 'Bolçu Savaşı\'nda Göktürkler Türgiş kağanını yenmiş, böylece batıdaki Türk boylarını yeniden kendilerine bağlamıştır.'),
  ('Asya Hunlarının Moğolistan\'dan batıya çekilmesinden sonra 2. yüzyılda bölgede egemenlik kuran topluluk hangisidir?', 'Siyenpiler', ['Göktürkler', 'Uygurlar', 'Hazarlar'], 'Kuzey Hunlarının zayıflayıp batıya çekilmesinden sonra Moğolistan bozkırına Siyenpiler hâkim olmuştur.'),
  ('Göktürk Devleti\'nin kurucusu Bumin\'den sonra tahta çıkan ve kısa süre hüküm sürdükten sonra yerini kardeşi Mukan\'a bırakan kağan kimdir?', 'Kara Kağan', ['Taspar Kağan', 'Kapgan Kağan', 'İşbara Kağan'], 'Bumin\'in oğlu Kara Kağan (Kolo) kısa bir süre hüküm sürmüş, ardından kardeşi Mukan Kağan tahta geçmiştir.'),
  ('Hunların görünüşünü, at üstündeki yaşamlarını ve savaş biçimlerini Avrupa\'ya ilk kez ayrıntılı biçimde anlatan 4. yüzyıl Romalı tarihçisi kimdir?', 'Ammianus Marcellinus', ['Priskos', 'Jordanes', 'Menandros Protektor'], 'Ammianus Marcellinus, Hunların Avrupa\'ya gelişini çağdaşı olarak anlatmış ve onları at sırtında yaşayan bir halk olarak tanıtmıştır.'),
  ('MÖ 119\'da Hunlara karşı büyük bir seferle Moğolistan bozkırına kadar ilerleyen ve Hunları kuzeye çekilmeye zorlayan Han komutanlarından biri kimdir?', 'Huo Qubing', ['Çang Kien', 'Sun Tzu', 'Konfüçyüs'], 'Han imparatoru Wudi döneminde Wei Qing ve Huo Qubing Hunlara karşı büyük seferler yapmış, Hunları Gobi\'nin kuzeyine çekilmeye zorlamıştır.'),
  ('558\'de İstanbul\'a elçi gönderip Bizans imparatoru I. Justinianus\'tan yurt ve yıllık ödeme isteyen, batıya yeni ulaşmış bozkır topluluğu hangisidir?', 'Avarlar', ['Hazarlar', 'Peçenekler', 'Kumanlar'], 'Göktürklerden kaçarak batıya gelen Avarlar 558\'de Bizans\'a elçi göndermiş; Bizans onları diğer bozkır topluluklarına karşı kullanmak üzere hediyelerle karşılamıştır.'),
  ('Kül Tigin yazıtına göre İlteriş Kutluk Kağan\'ın devleti yeniden kurarken kaç sefer yaptığı belirtilir?', 'Kırk yedi', ['On yedi', 'Yirmi', 'Yedi yüz'], 'Yazıtta İlteriş Kağan\'ın kırk yedi kez sefer ettiği ve yirmi kez savaştığı anlatılır. On yedi ve yedi yüz sayıları ise ayaklanmaya katılanların artışıyla ilgilidir.'),
  ('Göktürk Kağanlığı\'na bağlı boylar arasında sayılan ve Yakutların (Sahaların) ataları kabul edilen, Baykal Gölü çevresinde yaşayan topluluk hangisidir?', 'Kurıkanlar', ['Kırgızlar', 'Karluklar', 'Basmiller'], 'Orhun yazıtlarında \'Üç Kurıkan\' olarak geçen Kurıkanlar Baykal çevresinde yaşamış ve kuzeye göçerek bugünkü Yakutların oluşumuna katılmıştır.'),
  ('Asparuh\'un 680\'de Tuna deltası yakınlarında yenerek Bizans\'ı Tuna Bulgar Devleti\'ni tanımaya zorladığı Bizans imparatoru kimdir?', 'IV. Konstantinos', ['I. Justinianus', 'Herakleios', 'II. Basileios'], '680\'deki Ongal Savaşı\'nda IV. Konstantinos yenilmiş; Bizans ertesi yıl Bulgar devletini tanıyarak vergi ödemeyi kabul etmiştir.'),
  ('Tuna Bulgar Devleti\'nde Pliska\'dan sonra başkent yapılan ve 10. yüzyılda kültür merkezi olarak öne çıkan şehir hangisidir?', 'Preslav', ['Sarkel kalesi', 'Bulgar şehri', 'İtil'], 'Han Boris\'in oğulları döneminde başkent Preslav\'a taşınmış; şehir Slav yazı ve kilise kültürünün önemli bir merkezi olmuştur.'),
  ('Hazarların İdil deltasındaki İtil\'den önce başkent olarak kullandığı Kuzey Kafkasya şehirlerinden biri hangisidir?', 'Semender', ['Sarkel', 'Suyab', 'Koço'], 'Hazarlar başlangıçta Kuzey Kafkasya\'daki Belencer ve Semender\'i merkez edinmiş, Arap baskısı artınca başkenti kuzeydeki İtil\'e taşımıştır.'),
  ('Çin kaynaklarında \'yüksek tekerlekli arabalılar\' anlamına gelen bir adla da anılan ve Uygurların da içinden çıktığı geniş Türk boy topluluğu hangisidir?', 'Tölesler', ['Tabgaçlar', 'Kutrigurlar', 'Kumanlar'], 'Tölesler (Tiele) Çin kaynaklarında yüksek tekerlekli arabalar kullandıkları için bu adla da anılmıştır; Uygurlar da bu topluluktan çıkmıştır.'),
  ('Sarı Irmak\'ın büyük kıvrımı içinde kalan ve Hunlar ile Çin arasında sürekli el değiştiren otlak bölgesi hangisidir?', 'Ordos', ['Ötüken', 'Yedisu', 'Toharistan'], 'Ordos, Sarı Irmak\'ın kuzeye doğru yaptığı kıvrımın içindeki bozkırdır; Mete döneminde Hunlar burayı yeniden ele geçirmiş, Han hanedanı ise sonra geri almıştır.'),
  ('Türk tiyatrosunun bilinen en eski metinlerinden sayılan ve Buda\'nın hayatından sahneler içeren Uygurca Budist eser hangisidir?', 'Maytrısimit', ['Irk Bitig', 'Kutadgu Bilig', 'Huastuanift'], 'Maytrısimit, Uygurcaya çevrilmiş Budist bir eserdir; sahne düzenine uygun bölümleri nedeniyle Türk tiyatrosunun en eski örneklerinden sayılır.'),
  ('Uygur Maniheistlerinin günahlarından arınmak için okudukları tövbe duasını içeren Uygurca metin hangisidir?', 'Huastuanift', ['Altun Yaruk', 'Maytrısimit', 'Kalyanamkara ve Papamkara'], 'Huastuanift, Mani dinine bağlı Uygurların tövbe metnidir; diğerleri Budist eserlerdir.'),
  ('Uygurca Budist anlatılardan biri olan ve iyi kalpli bir prens ile kıskanç kardeşinin hikâyesini anlatan eser hangisidir?', 'Kalyanamkara ve Papamkara', ['Huastuanift', 'Irk Bitig', 'Oğuz Kağan Destanı'], '\'İyi Düşünceli ve Kötü Düşünceli Prens\' anlamına gelen bu Budist hikâye Uygurcaya çevrilmiş ve Dunhuang\'da bulunmuştur.'),
  ('Geleneksel anlatıya göre Attila\'nın 452\'de kuzey İtalya\'daki Aquileia\'yı yıkması üzerine kaçan halkın lagün adalarına sığınması hangi şehrin kökeniyle ilişkilendirilir?', 'Venedik', ['Roma', 'Milano', 'Napoli'], 'Hun saldırısından kaçanların Adriyatik kıyısındaki lagün adalarına yerleşmesi, Venedik\'in kuruluş anlatılarında önemli bir yer tutar.'),
  ('Annesi bir Kuman prensesi olduğu ve Kumanlarla yakın ilişkiler kurduğu için \'Kun\' lakabıyla anılan 13. yüzyıl Macar kralı kimdir?', 'IV. László', ['I. István', 'Matthias Corvinus', 'II. Lajos'], 'IV. László\'nun annesi Kuman kökenliydi; kral Kuman geleneklerine yakınlığı nedeniyle \'Kun László\' olarak anılmıştır.'),
  ('Kuzey Çin\'deki Yungang ve Longmen mağara tapınaklarındaki dev Buda heykellerinin yapımını destekleyen hanedan hangisidir?', 'Tabgaç (Kuzey Wei) hanedanı', ['Han hanedanı', 'Tang hanedanı', 'Qin hanedanı'], 'Tabgaç hükümdarları Budizmi desteklemiş; Yungang ve Longmen mağara tapınakları bu hanedan döneminde oyulmaya başlanmıştır.'),
  ('Bumin\'in kız isteğini aşağılayarak reddeden Juan-juan kağanı kimdir?', 'Anakuey (Anagui)', ['Şipi', 'Sulu (Türgiş kağanı)', 'Bayan'], 'Juan-juan kağanı Anakuey, Bumin\'in evlilik isteğini \'demirci kölem\' diyerek reddetmiş; bu olay Göktürk ayaklanmasının başlangıcı olmuştur.'),
  ('Batı Göktürk yabgularının yazlık merkezi olarak bilinen ve Çin kaynaklarında \'bin pınar\' anlamına gelen adla anılan yer hangi bölgededir?', 'Talas-Çu ırmakları çevresinde, Yedisu\'da', ['Orhun vadisinde, Ötüken\'de', 'Kırım\'ın güneyinde, Karadeniz kıyısında', 'İdil deltasında'], 'Batı Göktürklerin merkezleri Yedisu bölgesindeki Suyab ve \'Bin Pınar\' (Bingöl) çevresindeydi.'),
  ('Uygur hükümdarlarının yazılı emirlerine ve fermanlarına eski Türkçede verilen ad hangisidir?', 'Yarlığ', ['Bitig', 'Tamga', 'Sagu'], 'Yarlığ hükümdarın buyruğu, fermanıdır. Bitig yazı veya kitap, tamga mühür ve işaret, sagu ise ağıt anlamına gelir.'),
  ('Kansu\'ya göç eden Uygurların 9. ve 10. yüzyıllarda merkez edindiği şehir hangisidir?', 'Kançou', ['Koço', 'Ordu-Balık', 'Beşbalık'], 'Kansu Uygurları Kançou\'yu merkez yapmıştır; Koço ve Beşbalık ise Turfan Uygurlarının merkezleridir.'),
  ('Kül Tigin yazıtında Kül Tigin ile Bilge Kağan\'ın annesi olarak saygıyla anılan hatun kimdir?', 'İl Bilge Hatun', ['Çiçek Hatun', 'Umay Hatun', 'Tabgaç Hatun'], 'İlteriş Kutluk Kağan\'ın eşi İl Bilge Hatun, yazıtta oğullarının annesi olarak anılır ve devletin kuruluşundaki rolüyle saygı görür.'),
  ('Göktürk dönemine ait mezar başı insan heykellerinin çoğunda heykelin elinde tuttuğu nesne genellikle hangisidir?', 'Kap ya da kadeh', ['Kitap', 'Haç ya da dinî simge', 'Kalem'], 'Göktürk dönemi taş heykelleri çoğunlukla bir elinde kadeh tutan, belinde kılıç ya da kemer bulunan figürler olarak yapılmıştır.'),
  ('Eski Türklerde savaşta yararlılık gösterenlere verilen ve bazı vergi ile yükümlülüklerden muaf tutulmayı da içeren ayrıcalıklı unvan hangisidir?', 'Tarkan', ['Tigin', 'Kağan', 'Yabgu'], 'Tarkan unvanı askerî başarı karşılığında verilir ve sahibine vergi muafiyeti gibi ayrıcalıklar sağlardı.'),
  ('On iki hayvanlı Türk takviminde döngü hangi hayvanın yılıyla başlar?', 'Sıçan', ['At', 'Koyun', 'Ejderha'], 'Takvim sıçan yılıyla başlar; ardından öküz, pars, tavşan, ejderha, yılan, at, koyun, maymun, tavuk, köpek ve domuz yılları gelir.'),
  ('Priskos\'un anlatımına göre Attila\'nın Tisza ovasındaki sarayı ve çevresindeki yapıların büyük bölümü hangi malzemeden yapılmıştı?', 'Özenle işlenmiş ahşaptan', ['Mermer ve kireç taşından', 'Pişmiş tuğladan', 'Keçe ve deriden'], 'Priskos, Attila\'nın sarayının cilalı ahşap kalaslarla çevrili olduğunu, taş yapı olarak yalnızca bir hamamın bulunduğunu yazar.'),
];
